"""MavNext migration 002 tests (accounts, profiles, directory, join requests) — local PostgreSQL, NOT Supabase."""
import subprocess, json
U={n:f'{i}{i}{i}{i}{i}{i}{i}{i}-0000-0000-0000-00000000000{i}' for i,n in enumerate(['zed','ann','ben','cat','dan','eva','fay'],1)}
def q(sql, who=None):
    pre=''
    if who: pre=f"set role authenticated; set request.jwt.claim.sub='{U[who]}'; set request.jwt.claims='{json.dumps({'email':who+'@x.edu','sub':U[who]})}';"
    r=subprocess.run(['psql','-h','/tmp','-p','5499','-U','pg','-d','postgres','-tAq','-v','ON_ERROR_STOP=1','-c',pre+sql],capture_output=True,text=True)
    return (r.stdout.strip().splitlines()[-1] if r.stdout.strip() else ''), r.stderr.strip()
R=[]
def t(name, ok, detail=''): R.append((name,ok)); print('PASS' if ok else 'FAIL', name, '-', detail[:140])
meta=lambda n,c=True: json.dumps({'full_name':n.title()+' Tester','grad_term':'Spring 2027','major':'Information Systems', **({'consent_version':'2026-11-21'} if c else {})})
for n in ['ann','ben','cat','dan','eva']:
    q(f"insert into auth.users(id,email,raw_user_meta_data) values ('{U[n]}','{n}@x.edu','{meta(n)}')")
q(f"insert into auth.users(id,email,raw_user_meta_data) values ('{U['fay']}','fay@x.edu','{meta('fay',False)}')")
q(f"insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('{U['zed']}','zed@x.edu',null,'{meta('zed')}')")
o,_=q("select full_name||'|'||grad_term||'|'||consent_version from profiles",'ann'); t('sign-up creates profile from consented metadata', o=='Ann Tester|Spring 2027|2026-11-21', o)
o,_=q(f"select count(*) from profiles where user_id='{U['fay']}'"); t('no profile without consent', o=='0', o)
o,_=q("select count(*) from profiles",'ben'); t('profiles are private to their owner', o=='1', o)
o,e=q(f"update profiles set full_name='Hacked' where user_id='{U['ann']}' returning user_id",'ben'); t('cannot edit another profile', o=='', f'{o!r} {e}')
o,e=q("update profiles set consent_at='2000-01-01' returning consent_at::date",'ann'); t('consent time cannot be backdated', o!='2000-01-01', o)
o,e=q("insert into profiles(user_id,full_name,consent_version) values (auth.uid(),'Fay','2026-11-21') returning full_name",'fay'); t('user without profile can complete own profile', o=='Fay', e)
org,e=q("select create_organization('Nepalese Student Association','','Spring 2027','President')",'ann')
o,_=q(f"select (data->>'name')||'|'||(data->>'title')||'|'||permission from memberships where org_id='{org}'",'ann'); t('create_organization: profile name + title, admin', o=='Ann Tester|President|admin', o)
o,e=q("select create_organization('x')",'ben'); t('org name length enforced', 'must be 2-120' in e, e)
priv,_=q("select create_organization('Private Club')",'eva'); q(f"update organizations set listed=false where id='{priv}'",'eva')
o,_=q("select string_agg(name,',' order by name) from org_directory('')",'ben'); t('directory lists names of listed orgs only', o=='Nepalese Student Association', o)
o,_=q("select count(*) from org_directory('nepal')",'ben'); t('directory search', o=='1', o)
o,e=q("select count(*) from org_directory('')"); 
o,e=q("set role anon; select count(*) from org_directory('')"); t('anonymous cannot use directory', 'permission denied' in e, e)
o,_=q(f"select count(*) from organizations where id='{org}'",'ben'); t('directory does not grant read access to org', o=='0', o)
o,e=q(f"insert into join_requests(org_id,org_name,user_id,requester_name,requester_email) values('{org}','x','{U['ben']}','Ben','b')",'ben'); t('no direct inserts into join_requests', 'row-level security' in e or 'permission' in e, e)
req,e=q(f"select request_to_join('{org}','Treasurer','I was elected treasurer')",'ben'); t('request_to_join works', bool(req) and not e, e)
o,e=q(f"select request_to_join('{org}','x','y')",'ben'); t('only one pending request per org', 'already have a pending request' in e, e)
o,e=q(f"select request_to_join('{priv}','x','y')",'ben'); t('cannot request unlisted org', 'not found' in e, e)
o,e=q(f"select request_to_join('{org}','x','y')",'zed'); t('a second user can also request (one pending each)', bool(o), e)
o,_=q(f"select count(*) from memberships where org_id='{org}' and user_id='{U['ben']}'"); t('pending request grants no membership', o=='0', o)
o,_=q("select count(*) from join_requests",'cat'); t('other users cannot see requests', o=='0', o)
o,_=q("select requester_name||'|'||desired_title||'|'||status from join_requests where user_id=auth.uid()",'ben'); t('requester sees own request', o=='Ben Tester|Treasurer|pending', o)
o,_=q(f"select count(*) from join_requests where org_id='{org}'",'ann'); t('admin sees org requests', o=='2', o)
o,e=q(f"select decide_join_request('{req}', true, 'admin', '')",'ben'); t('requester cannot approve self', 'only an administrator' in e, e)
o,e=q(f"select decide_join_request('{req}', true, 'officer', 'Treasurer')",'ann'); t('admin approves', bool(o) and not e, e)
o,_=q(f"select permission||'|'||(data->>'title')||'|'||status from memberships where org_id='{org}' and user_id='{U['ben']}'"); t('approved member has chosen permission/title', o=='officer|Treasurer|active', o)
o,_=q(f"select count(*) from organizations where id='{org}'",'ben'); t('approved member can now read org', o=='1', o)
o,_=q(f"select count(*) from activity where org_id='{org}'",'ann'); t('approval recorded in activity', o=='1', o)
o,e=q(f"select decide_join_request('{req}', true, 'admin', '')",'ann'); t('request cannot be decided twice', 'already decided' in e, e)
zreq,_=q(f"select id from join_requests where user_id='{U['zed']}'")
o,e=q(f"select cancel_join_request('{zreq}')",'ben'); t('cannot cancel someone else\'s request', 'not found' in e, e)
o,e=q(f"select cancel_join_request('{zreq}')",'zed'); t('requester can cancel own', not e, e)
# invitations: expiry + confirmed email
tok,_=q(f"insert into invitations(org_id,email,permission,data) values('{org}','cat@x.edu','incoming','{{\"title\":\"VP-elect\"}}') returning token",'ann')
o,e=q(f"select accept_invitation('{tok}')",'zed'); t('unconfirmed email cannot accept invitation', 'confirm your email' in e, e)
old,_=q(f"insert into invitations(org_id,email,permission,expires_at) values('{org}','dan@x.edu','officer',now()-interval '1 day') returning token",'ann')
o,e=q(f"select accept_invitation('{old}')",'dan'); t('expired invitation rejected', 'expired' in e, e)
o,e=q(f"select accept_invitation('{tok}')",'cat'); t('valid invitation accepted', bool(o) and not e, e)
o,_=q(f"select data->>'name' from memberships where org_id='{org}' and user_id='{U['cat']}'"); t('invited member gets profile name', o=='Cat Tester', o)
# leave + last admin
o,e=q(f"select leave_organization('{org}')",'ann'); t('last admin cannot leave', 'last administrator' in e, e)
o,e=q(f"select leave_organization('{org}')",'ben'); t('member can leave', not e, e)
o,_=q(f"select count(*) from organizations where id='{org}'",'ben'); t('after leaving, no access', o=='0', o)
req2,_=q(f"select request_to_join('{org}','Treasurer','back again')",'ben'); q(f"select decide_join_request('{req2}', true, 'officer', '')",'ann')
o,_=q(f"select status from memberships where org_id='{org}' and user_id='{U['ben']}'"); t('former member can rejoin through approval', o=='active', o)
o,e=q(f"select mn_upsert_membership('{org}','{U['dan']}','admin','{{}}')",'dan'); t('internal membership helper not callable', 'permission denied' in e, e)
print(f"\n{sum(ok for _,ok in R)}/{len(R)} passed")
json.dump([{'test':n,'pass':ok} for n,ok in R], open('rls_results2.json','w'), indent=1)
